terraform {
  required_version = ">= 1.11.0"

  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.9"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.9"
    }
  }
}

# A random two-word name, such as "proud-otter".
resource "random_pet" "site" {
  length = 2
}

# A file whose content refers to the pet's name: an implicit dependency.
resource "local_file" "index" {
  filename = "${path.module}/site/index.html"
  content  = "<h1>Hello from ${random_pet.site.id}</h1>\n"
}

# terraform_data is built in: no provider needed. Its input can change without replacing it.
resource "terraform_data" "release" {
  input = {
    version = "1.0.0"
    page    = local_file.index.filename
  }
}

output "site_name" {
  value = random_pet.site.id
}

terraform {
  required_version = ">= 1.11.0"

  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.9"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.9"
    }
  }
}

locals {
  total_replicas = sum([for s in var.services : s.replicas])
}

# One API key per service: for_each makes one instance per map key.
resource "random_password" "api_key" {
  for_each = var.services

  length  = 24
  special = false
}

resource "local_file" "service_config" {
  for_each = var.services

  filename        = "${path.module}/out/${var.environment}/${each.key}.env"
  file_permission = "0640"
  content         = <<-EOT
    SERVICE=${each.key}
    ENVIRONMENT=${var.environment}
    PORT=${each.value.port}
    REPLICAS=${each.value.replicas}
    OWNER=${var.owner}
  EOT
}

variable "environment" {
  description = "The environment to configure: dev or prod."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "The environment must be \"dev\" or \"prod\"."
  }
}

variable "services" {
  description = "The services to configure, with their port and number of replicas."
  type = map(object({
    port     = number
    replicas = optional(number, 1)
  }))
}

variable "owner" {
  description = "The team that owns these services."
  type        = string
  default     = "platform-team"
}

output "config_files" {
  description = "The configuration file written for each service."
  value       = { for name, f in local_file.service_config : name => f.filename }
}

output "total_replicas" {
  description = "Replicas across all services."
  value       = local.total_replicas
}

output "api_keys" {
  description = "Each service's API key."
  value       = { for name, p in random_password.api_key : name => p.result }
  sensitive   = true
}

environment = "dev"

services = {
  api    = { port = 8080 }
  worker = { port = 9090 }
}

environment = "prod"

services = {
  api    = { port = 8080, replicas = 3 }
  worker = { port = 9090, replicas = 2 }
  web    = { port = 80, replicas = 2 }
}

terraform {
  required_version = ">= 1.11.0"

  # Step 3 adds the backend: uncomment these lines, then run terraform init -migrate-state.
  # backend "pg" {}

  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.9"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.14"
    }
  }
}

variable "hold_seconds" {
  description = "How long the apply holds the state lock, for the locking experiment."
  type        = number
  default     = 1
}

resource "local_file" "report" {
  filename = "${path.module}/out/report.txt"
  content  = "Inventory report\n"
}

# Waits while it's created, so an apply keeps the state lock long enough to see locking at work.
resource "time_sleep" "hold" {
  create_duration = "${var.hold_seconds}s"
  triggers = {
    seconds = var.hold_seconds
  }
}

terraform {
  required_version = ">= 1.11.0"

  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 4.6"
    }
  }
}

provider "docker" {}

# One set of settings per workspace; terraform.workspace picks the right one.
locals {
  settings = {
    dev  = { replicas = 1, base_port = 8081, message = "Hello from dev" }
    prod = { replicas = 2, base_port = 8091, message = "Hello from prod" }
  }
  known = contains(keys(local.settings), terraform.workspace)
  env   = local.settings[local.known ? terraform.workspace : "dev"]
}

module "web" {
  source = "./modules/web"

  name      = "shop-${terraform.workspace}"
  replicas  = local.env.replicas
  base_port = local.env.base_port
  message   = local.env.message
}

# Stops a plan, with a clear message, in a workspace without settings, such as "default".
resource "terraform_data" "workspace_guard" {
  input = terraform.workspace

  lifecycle {
    precondition {
      condition     = local.known
      error_message = "Workspace \"${terraform.workspace}\" has no settings: run terraform workspace select dev (or prod)."
    }
  }
}

output "urls" {
  value = module.web.urls
}

terraform {
  required_version = ">= 1.11.0"

  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 4.6"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.9"
    }
  }
}

variable "name" {
  description = "Prefix for every resource the module creates, such as shop-dev."
  type        = string
}

variable "replicas" {
  description = "How many web containers to run."
  type        = number
  default     = 1

  validation {
    condition     = var.replicas >= 1 && var.replicas <= 5
    error_message = "replicas must be between 1 and 5."
  }
}

variable "base_port" {
  description = "Host port for the first container; each further replica uses the next port."
  type        = number
}

variable "message" {
  description = "Text for the page the containers serve."
  type        = string
}

resource "docker_network" "this" {
  name = "${var.name}-net"
}

resource "docker_image" "nginx" {
  name         = "nginx:1.31-alpine"
  keep_locally = true
}

resource "local_file" "index" {
  filename = "${path.root}/build/${var.name}/index.html"
  content  = "<h1>${var.message}</h1>\n"
}

resource "docker_container" "web" {
  count = var.replicas

  name  = "${var.name}-web-${count.index}"
  image = docker_image.nginx.image_id

  ports {
    internal = 80
    external = var.base_port + count.index
  }

  networks_advanced {
    name = docker_network.this.name
  }

  volumes {
    host_path      = abspath(dirname(local_file.index.filename))
    container_path = "/usr/share/nginx/html"
    read_only      = true
  }
}

output "urls" {
  description = "Where each replica can be reached from your computer."
  value       = [for c in docker_container.web : "http://localhost:${c.ports[0].external}"]
}

output "network" {
  description = "The Docker network the containers share."
  value       = docker_network.this.name
}

