# Unit tests for the web module. The mock providers stand in for Docker and the file system,
# so the tests run anywhere, in seconds, and create nothing.
mock_provider "docker" {}
mock_provider "local" {}

variables {
  name      = "test"
  replicas  = 2
  base_port = 9000
  message   = "hello"
}

run "replicas_get_consecutive_ports" {
  command = plan

  assert {
    condition     = [for c in docker_container.web : c.ports[0].external] == [9000, 9001]
    error_message = "Each replica must publish the next host port."
  }

  assert {
    condition     = docker_container.web[1].name == "test-web-1"
    error_message = "Containers must be named <name>-web-<index>."
  }
}

run "rejects_too_many_replicas" {
  command = plan

  variables {
    replicas = 9
  }

  expect_failures = [var.replicas]
}

run "outputs_one_url_per_replica" {
  command = apply

  assert {
    condition     = output.urls == ["http://localhost:9000", "http://localhost:9001"]
    error_message = "The urls output must list one address per replica."
  }
}
